/**
 * Restore the OG image cache into dist/og after a Vite build.
 *
 * `vite build` empties dist/ — including the OG images generated by
 * `generate-og-images.mjs` (build:release). That script caches its output in
 * `.og-cache/`; this helper copies the cache back so a plain `npm run build`
 * never accidentally strips the social images from the next deploy.
 *
 * Runs in milliseconds. `npm run build:release` regenerates the cache first.
 */
import { cpSync, existsSync, readdirSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const cache = path.join(ROOT, '.og-cache');
const target = path.join(ROOT, 'dist', 'og');

const nonEmpty = (dir) =>
  existsSync(dir) && readdirSync(dir, { withFileTypes: true }).some((e) =>
    e.isDirectory() ? nonEmpty(path.join(dir, e.name)) : true,
  );

if (nonEmpty(target)) {
  console.log('[og] dist/og already populated — nothing to restore.');
  process.exit(0);
}
if (!nonEmpty(cache)) {
  console.log('[og] No .og-cache found — skipping (dev build without OG images).');
  process.exit(0);
}
cpSync(cache, target, { recursive: true });
const files = existsSync(target) ? readdirSync(target).length : 0;
console.log(`[og] Restored cached OG images into dist/og (${files} sections).`);